<?php
require dirname(__DIR__).'/app/bootstrap.php';
function admin_user(){return $_SESSION['admin']??null;} function require_admin(){if(!admin_user()){header('Location: /admin/?login=1');exit;}} function can_manage_users(){return (admin_user()['role']??'')==='superadmin';}
$action=$_GET['action']??'dashboard';$message='';
if($action==='logout'){session_destroy();header('Location: /admin/');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&($action==='login'||$action==='save')){csrf_check();if($action==='login'){$q=db()->prepare('SELECT id,name,username,password_hash,role FROM users WHERE username=? LIMIT 1');$q->execute([trim($_POST['username'])]);$u=$q->fetch();if($u&&password_verify($_POST['password'],$u['password_hash'])){session_regenerate_id(true);unset($u['password_hash']);$_SESSION['admin']=$u;header('Location: /admin/');exit;}$message='Invalid username or password.';}else{require_admin();$type=$_POST['type']??'post';$id=(int)($_POST['id']??0);$slug=preg_replace('/[^a-z0-9]+/','-',strtolower(trim($_POST['slug']?:$_POST['title'])));$data=[trim($_POST['title']),$slug,trim($_POST['excerpt']),$_POST['body']??'',$_POST['status']??'draft',trim($_POST['meta_title']),trim($_POST['meta_description'])];if($id){$q=db()->prepare('UPDATE content SET title=?,slug=?,excerpt=?,body=?,status=?,meta_title=?,meta_description=?,published_at=IF(?="published",NOW(),published_at) WHERE id=?');$q->execute([...$data,$data[4],$id]);}else{$q=db()->prepare('INSERT INTO content(type,title,slug,excerpt,body,status,meta_title,meta_description,published_at) VALUES(?,?,?,?,?,?,?,?,IF(?="published",NOW(),NULL))');$q->execute([$type,...$data,$data[4]]);}$message='Content saved.';$action='content';}}
if(!admin_user()): ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin login | Ellen's Florist</title><link rel="stylesheet" href="/assets/css/main.css"></head><body><main class="section tinted" style="min-height:100vh;display:grid;place-items:center"><form class="form-wrap" method="post" style="width:min(440px,100%)"><p class="eyebrow">Ellen’s Florist</p><h1 style="font-size:2.5rem">Admin login</h1><?php if($message):?><div class="alert"><?=e($message)?></div><?php endif?><input type="hidden" name="csrf" value="<?=csrf()?>"><p><label>Username</label><input required name="username" autocomplete="username"></p><p><label>Password</label><input required type="password" name="password" autocomplete="current-password"></p><button class="button gold">Sign in</button></form></main></body></html><?php exit;endif;
$content=[];if(in_array($action,['content','edit'],true)){$content=db()->query('SELECT * FROM content ORDER BY updated_at DESC')->fetchAll();}$edit=null;if($action==='edit'&&isset($_GET['id'])){$q=db()->prepare('SELECT * FROM content WHERE id=?');$q->execute([(int)$_GET['id']]);$edit=$q->fetch();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin | Ellen's Florist</title><link rel="stylesheet" href="/assets/css/main.css"><style>.admin{display:grid;grid-template-columns:230px 1fr;min-height:100vh}.admin aside{background:#2b2b2b;color:#faf8f5;padding:25px}.admin aside a{display:block;padding:9px 0}.admin main{padding:clamp(25px,5vw,60px)}table{width:100%;border-collapse:collapse;background:#fff}th,td{text-align:left;padding:12px;border-bottom:1px solid #eee}@media(max-width:700px){.admin{grid-template-columns:1fr}.admin aside{display:flex;gap:15px;flex-wrap:wrap}.admin aside a{padding:0}}</style></head><body><div class="admin"><aside><div class="brand"><span>EF</span><b>Ellen's Florist</b><small>Admin panel</small></div><hr><a href="/admin/">Dashboard</a><a href="/admin/?action=content">Content & Blog</a><a href="/admin/?action=edit">Add content</a><a href="/admin/?action=inquiries">Wedding inquiries</a><a href="/admin/?action=messages">Contact messages</a><?php if(can_manage_users()):?><a href="/admin/?action=users">Team & roles</a><?php endif?><a href="/admin/?action=logout">Log out</a></aside><main><?php if($message):?><div class="alert"><?=e($message)?></div><?php endif?>
<?php if($action==='dashboard'):?><p class="eyebrow">Welcome, <?=e(admin_user()['name'])?></p><h1 style="font-size:3rem">Dashboard</h1><div class="cards"><div class="card"><h3>Wedding inquiries</h3><p>Review new celebration requests and follow up promptly.</p><a href="?action=inquiries">Open inquiries →</a></div><div class="card"><h3>Content</h3><p>Publish journal posts, pages, packages, testimonials, and gallery work.</p><a href="?action=content">Manage content →</a></div></div>
<?php elseif($action==='content'):?><h1 style="font-size:3rem">Content</h1><p><a class="button gold" href="?action=edit">Add content</a></p><table><tr><th>Title</th><th>Type</th><th>Status</th><th>Updated</th><th></th></tr><?php foreach($content as $row):?><tr><td><?=e($row['title'])?></td><td><?=e($row['type'])?></td><td><?=e($row['status'])?></td><td><?=e($row['updated_at'])?></td><td><a href="?action=edit&id=<?=$row['id']?>">Edit</a></td></tr><?php endforeach?></table>
<?php elseif($action==='edit'): $edit=$edit?:['id'=>'','type'=>'post','title'=>'','slug'=>'','excerpt'=>'','body'=>'','status'=>'draft','meta_title'=>'','meta_description'=>''];?><h1 style="font-size:3rem"><?= $edit['id']?'Edit':'Add' ?> content</h1><form method="post" class="form-wrap"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=e((string)$edit['id'])?>"><div class="form-grid"><p><label>Content type</label><select name="type"><?php foreach(['post','page','gallery','testimonial','package','faq'] as $t):?><option <?=$edit['type']===$t?'selected':''?>><?=$t?></option><?php endforeach?></select></p><p><label>Status</label><select name="status"><option <?=$edit['status']==='draft'?'selected':''?>>draft</option><option <?=$edit['status']==='published'?'selected':''?>>published</option></select></p><p class="full"><label>Title</label><input required name="title" value="<?=e($edit['title'])?>"></p><p class="full"><label>URL slug</label><input name="slug" value="<?=e($edit['slug'])?>"></p><p class="full"><label>Excerpt</label><textarea name="excerpt"><?=e($edit['excerpt'])?></textarea></p><p class="full"><label>Content (HTML supported)</label><textarea name="body" style="min-height:300px"><?=e($edit['body'])?></textarea><small class="help">Use the HTML editor for rich content; media uploads can be managed through cPanel until a WYSIWYG library is added.</small></p><p><label>SEO title</label><input name="meta_title" value="<?=e($edit['meta_title'])?>"></p><p><label>SEO description</label><input name="meta_description" value="<?=e($edit['meta_description'])?>"></p><p class="full"><button class="button gold">Save content</button></p></div></form>
<?php elseif(in_array($action,['inquiries','messages'],true)):$table=$action==='inquiries'?'inquiries':'contact_messages';$rows=db()->query("SELECT * FROM $table ORDER BY created_at DESC LIMIT 100")->fetchAll();?><h1 style="font-size:3rem"><?=ucfirst(str_replace('_',' ',$table))?></h1><table><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $head):?><th><?=e($head)?></th><?php endforeach?></tr><?php foreach($rows as $row):?><tr><?php foreach($row as $value):?><td><?=e((string)$value)?></td><?php endforeach?></tr><?php endforeach?><?php else:?><tr><td>No records yet.</td></tr><?php endif?></table>
<?php else:?><h1 style="font-size:3rem">Coming soon</h1><p>This area is reserved for staff management. Only superadmins may manage team accounts and roles.</p><?php endif?></main></div></body></html>
